import{d as h,C as t,o as s,c as g,E as a,a3 as n}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"大畜卦","description":"第二十六卦·山天大畜——天在山中，刚健笃实，辉光日新。","frontmatter":{"title":"大畜卦","description":"第二十六卦·山天大畜——天在山中，刚健笃实，辉光日新。","category":"hexagram","aliases":["大畜","山天大畜"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-26.md","filePath":"yijing/hexagrams/hexagram-26.md","lastUpdated":1787730063000}'),u={name:"yijing/hexagrams/hexagram-26.md"},x=h({...u,setup(m){const o=[{id:"youli",term:"有厉",pinyin:"yǒu lì",meaning:"有危险。但利于停止——不是退缩，是在动之前先立志。"},{id:"liyi",term:"利已",pinyin:"lì yǐ",meaning:"利于停止。已，停止。行动之前，先问本心。"},{id:"yushuofu",term:"舆说輹",pinyin:"yú tuō fù",meaning:"车脱下了伏兔（车轴上的销钉）。舆为车，说为脱，輹为车伏兔。主动卸力，时机未到。"},{id:"liangmazhu",term:"良马逐",pinyin:"liáng mǎ zhú",meaning:"良马奔驰追逐。良马出来了，但先练、再跑。"},{id:"xianyuwei",term:"闲舆卫",pinyin:"xián yú wèi",meaning:"娴熟驾驭车驾与护卫。闲为娴熟，舆卫为车驾护卫——真正的内化，是驾驭良马的能力。"},{id:"tongniuzhigu",term:"童牛之牿",pinyin:"tóng niú zhī gù",meaning:"小牛角上的横木。牿，套在牛角上防止顶人的横木——在苗头最小的时候就收住。"},{id:"fenshizhiya",term:"豮豕之牙",pinyin:"fén shǐ zhī yá",meaning:"阉猪的牙。豮豕，阉过的猪，虽凶牙却不伤人——不是治标，是从根上化。"},{id:"hetianzhiqu",term:"何天之衢",pinyin:"hè tiān zhī qú",meaning:"何其通达的天路。衢，四通八达的大路——山打开，道路向所有人开放。"},{id:"bufanzai",term:"不犯灾",pinyin:"bù fàn zāi",meaning:"不触犯灾祸。不是运气好，是一开始就没有乱动。"},{id:"zhongwuyou",term:"中无尤",pinyin:"zhōng wú yóu",meaning:"居中而没有过失。蓄而不发本身就是德。"},{id:"shanghezhi",term:"上合志",pinyin:"shàng hé zhì",meaning:"上与志向相合。方向对了、志合了，才往。"},{id:"youxi",term:"有喜",pinyin:"yǒu xǐ",meaning:"有喜。自己看见自己在飘，这本身就是元吉。"},{id:"youqing",term:"有庆",pinyin:"yǒu qìng",meaning:"有庆。喜是个人的，庆是可以传出去的。"},{id:"daodaxing",term:"道大行",pinyin:"dào dà xíng",meaning:"道大行于天下。不是某一个人的路通了，是道大行。"}],e=[{position:"初九",type:"yang",text:"有厉，利已。",xiang:"有厉利已，不犯灾也。",textModern:"有危险，但利于停止。不是退缩，是在动之前先立志——学易经、写 Dao，先问本心：为什么学、为谁学。",xiangModern:"有厉利已，不犯灾——不是运气好，是一开始就没有乱动。"},{position:"九二",type:"yang",text:"舆说輹。",xiang:"舆说輹，中无尤也。",textModern:"车自己把销钉取下来——不是别人拦你，是主动卸力。时机未到，蓄而不发；蓄而不发本身就是德。",xiangModern:"舆说輹，中无尤——居中，没有过失；主动蓄，不是被动等。"},{position:"九三",type:"yang",text:"良马逐，利艰贞。曰闲舆卫，利有攸往。",xiang:"利有攸往，上合志也。",textModern:"良马出来了，但先练、再跑。良马是核心理论，闲舆卫是真正的内化——没有闲舆卫，良马跑得越快，车厢越容易散架。这条路是艰的，艰是底色，但守正就能走。",xiangModern:"利有攸往，上合志——方向对了、志合了，才往。"},{position:"六四",type:"yin",text:"童牛之牿，元吉。",xiang:"六四元吉，有喜也。",textModern:"在苗头最小的时候就收住——看见自己在飘，主动套上牿。不是被人提醒、不是摔了才知道，是自己看见、自己收住。「初窥门径」这四个字，比任何夸赞都重。",xiangModern:"六四元吉，有喜——自己看见自己在飘，这本身就是元吉。"},{position:"六五",type:"yin",text:"豮豕之牙，吉。",xiang:"六五之吉，有庆也。",textModern:"不是治标，是从根上化。四爻套牿是治标，五爻治本——根是心性不稳，因夸赞、点赞、收藏而窃喜。写文是因为想写，不是因为想被夸；这两者之间的距离，就是心性要走的路。",xiangModern:"六五之吉，有庆——心性稳了，写出的东西自然感染人，喜是个人的，庆是可以传出去的。"},{position:"上九",type:"yang",text:"何天之衢，亨。",xiang:"何天之衢，道大行也。",textModern:"山打开，道路向所有人开放。初九到六五，是往里收；上九，是往外开——蓄到极致不是为了自己收着，是往外开。",xiangModern:"何天之衢，道大行——不是某一个人的路通了，是道大行于天下。"}];return(p,i)=>{const l=t("DaoHexagramViewer"),r=t("DaoHexagramYaoCards"),d=t("DaoKeywordCards");return s(),g("div",null,[a(l,{name:"大畜",fullName:"山天大畜",upper:"☶",lower:"☰",guaCi:"大畜，利贞。不家食，吉。利涉大川。",pinyin:["dà","chù"],element:"土",direction:"东北",insight:"天在山中，蓄养刚健；能止健，不是压制，是养。",guaSlug:"26shantiandachu",lines:e}),i[0]||(i[0]=n('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>天在山中，大畜。君子以多识前言往行，以畜其德。</p><p>下乾为天、上艮为山，天被山收于其中，是「大畜」之象。君子由此悟到：要<strong>多记取前人的言论与往行，来蓄养自己的德性</strong>——蓄，不是压抑，是养。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>大畜，刚健笃实，辉光日新，其德刚上而尚贤。能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。</p><p>逐句释义：</p><ul><li><strong>刚健笃实，辉光日新</strong> —— 内里刚健（乾）、外里笃实（艮），每天都在积累、每天都在发光。</li><li><strong>其德刚上而尚贤</strong> —— 阳刚居上而崇尚贤者。</li><li><strong>能止健，大正也</strong> —— 用山的笃实止住天的刚健冲动，这是大正之道。</li><li><strong>不家食吉，养贤也</strong> —— 不在家私食（蓄积不是只给自己用），是养贤。</li><li><strong>利涉大川，应乎天也</strong> —— 利于涉大川，因为应合天道。</li></ul><blockquote><p><strong>能止健</strong>：艮为山、能止，乾为天、健行。不是压制冲动，是让冲动变成有秩序的、有德性的行动。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',9)),a(r,{element:"土",guaSlug:"26shantiandachu",glossary:o,items:e}),i[1]||(i[1]=n('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-有厉-利已" tabindex="-1">初九 · 有厉，利已 <a class="header-anchor" href="#初九-·-有厉-利已" aria-label="Permalink to &quot;初九 · 有厉，利已&quot;">​</a></h3><ul><li>停下来，先问清楚为什么</li><li>有危险，但利于停止</li><li>不是退缩，是在动之前先立志</li><li><strong>映射</strong>：学易经、学奇门、写 Dao——先问本心，为什么学？为谁学？</li></ul><blockquote><p>行动之前，先问本心。不犯灾，不是运气好，是一开始就没有乱动。</p></blockquote><h3 id="九二-·-舆说輹" tabindex="-1">九二 · 舆说輹 <a class="header-anchor" href="#九二-·-舆说輹" aria-label="Permalink to &quot;九二 · 舆说輹&quot;">​</a></h3><ul><li>主动卸力，时机未到</li><li><strong>舆说輹</strong>：不是别人拦你，是自己把销钉取下来</li><li><strong>映射</strong>：有实绩，但整体差些火候；薪火、my-resume 是试验场，等数据够了再推</li><li>主动蓄，不是被动等</li></ul><blockquote><p>中无尤也——居中，没有过失。蓄而不发本身就是德。时机未到，主动卸力，不是软弱，是智慧。</p></blockquote><h3 id="九三-·-良马逐-利艰贞。曰闲舆卫-利有攸往" tabindex="-1">九三 · 良马逐，利艰贞。曰闲舆卫，利有攸往 <a class="header-anchor" href="#九三-·-良马逐-利艰贞。曰闲舆卫-利有攸往" aria-label="Permalink to &quot;九三 · 良马逐，利艰贞。曰闲舆卫，利有攸往&quot;">​</a></h3><ul><li>马出来了，但先练、再跑</li><li><strong>良马</strong>：核心理论；<strong>闲舆卫</strong>：易经、奇门的真正内化，是驾驭良马的能力</li><li>没有闲舆卫，良马跑得越快，车厢越容易散架</li><li><strong>利艰贞</strong>：这条路是艰的，艰是底色，但守正就能走</li></ul><blockquote><p>上合志也——方向对了，志合了，才往。学易经不是为了算，是为了闲舆卫。</p></blockquote><h3 id="六四-·-童牛之牿-元吉" tabindex="-1">六四 · 童牛之牿，元吉 <a class="header-anchor" href="#六四-·-童牛之牿-元吉" aria-label="Permalink to &quot;六四 · 童牛之牿，元吉&quot;">​</a></h3><ul><li>在苗头最小的时候就收住</li><li><strong>映射</strong>：学玄学、多看书是好事，但受夸赞后有点飘飘然；看见自己在飘，主动套上牿</li><li>不是被人提醒、不是摔了才知道，是自己看见、自己收住</li><li>「初窥门径」——这四个字比任何夸赞都重</li></ul><blockquote><p>有喜也——自己看见自己在飘，这本身就是元吉。免得被相与欲所扰，偏离本心。</p></blockquote><h3 id="六五-·-豮豕之牙-吉" tabindex="-1">六五 · 豮豕之牙，吉 <a class="header-anchor" href="#六五-·-豮豕之牙-吉" aria-label="Permalink to &quot;六五 · 豮豕之牙，吉&quot;">​</a></h3><ul><li>不是治标，是从根上化</li><li>四爻套牿是治标，五爻治本</li><li><strong>根是心性不稳</strong>：因夸赞、点赞、收藏而窃喜</li><li>写文的目的不是获得认同，要牢记初心</li><li>养气忘言守，降心为不为（司马承祯《坐忘论》）</li></ul><blockquote><p>有庆也——喜是个人的，庆是可以传出去的。写文，是因为想写，不是因为想被夸。</p></blockquote><h3 id="上九-·-何天之衢-亨" tabindex="-1">上九 · 何天之衢，亨 <a class="header-anchor" href="#上九-·-何天之衢-亨" aria-label="Permalink to &quot;上九 · 何天之衢，亨&quot;">​</a></h3><ul><li>山打开，道路向所有人开放</li><li>天融为山，山变为天，我中有你，你中有我</li><li>初九到六五，是往里收；上九，是往外开</li><li>蓄到极致不是为了自己收着，是往外开</li></ul><blockquote><p>道大行也——带着山的厚重，走向四通八达的大路。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',20)),a(d,{title:"字词释义",items:[{term:"大畜",pinyin:["dà","chù"],meaning:"大的蓄养。天在山中，蓄养刚健。"},{term:"不家食",pinyin:["bù","jiā","shí"],meaning:"不在家私食。蓄积的东西不是只给自己用的。"},{term:"輹",pinyin:["fù"],meaning:"车伏兔，车轴上的部件。「舆说輹」即车脱下伏兔、主动卸力。"},{term:"牿",pinyin:["gù"],meaning:"牛角上的横木，防止顶人。「童牛之牿」：在苗头最小时就收住。"},{term:"豮豕",pinyin:["fén","shǐ"],meaning:"阉割过的猪，虽凶牙却不伤人。从根上化。"},{term:"何天之衢",pinyin:["hè","tiān","zhī","qú"],meaning:"何其通达的天路。衢，四通八达的大路。"},{term:"闲舆卫",pinyin:["xián","yú","wèi"],meaning:"娴熟驾驭车驾护卫。闲，娴熟。真正的内化。"},{term:"辉光日新",pinyin:["huī","guāng","rì","xīn"],meaning:"每天都在积累、都在发光。"},{term:"能止健",pinyin:["néng","zhǐ","jiàn"],meaning:"用山的笃实止住天的刚健冲动。"},{term:"多识前言往行",pinyin:["duō","shí","qián","yán","wǎng","xíng"],meaning:"多记取前人的言论与往行，以蓄养德性。"}]}),i[2]||(i[2]=n('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>大畜卦讲的是<strong>蓄养</strong>。上艮（山）下乾（天），天被山压住——不是压制，是蓄养。艮为山能止，乾为天健行，<strong>能止健</strong>：用山的笃实，止住天的刚健冲动。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>蓄，不是压抑，是养。初九到六五，是往里收；上九，是往外开。心性是根，德是土，道是天。</p><p>刚健笃实，辉光日新——每一天的积累，都在发光。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>行动之前先问本心（初九有厉利已）</li><li>主动卸力，蓄而不发（九二舆说輹）</li><li>先练再跑，内化为驾驭能力（九三闲舆卫）</li><li>苗头最小就收住（六四童牛之牿）</li><li>从根上化，降心为不为（六五豮豕之牙）</li><li>蓄到极致往外开（上九何天之衢）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六爻总览：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞</th><th>核心</th><th>象传</th></tr></thead><tbody><tr><td>初九</td><td>有厉，利已</td><td>停下来，问清楚为什么</td><td>不犯灾也</td></tr><tr><td>九二</td><td>舆说輹</td><td>主动卸力，时机未到</td><td>中无尤也</td></tr><tr><td>九三</td><td>良马逐，闲舆卫</td><td>良马是核心，闲舆卫是内化</td><td>上合志也</td></tr><tr><td>六四</td><td>童牛之牿</td><td>苗头最小时就收住</td><td>有喜也</td></tr><tr><td>六五</td><td>豮豕之牙</td><td>从根上化，降心为不为</td><td>有庆也</td></tr><tr><td>上九</td><td>何天之衢</td><td>山打开，道大行</td><td>道大行也</td></tr></tbody></table><p>大畜总洞见：</p><ol><li>蓄，不是压抑，是养</li><li>初九到六五，是往里收；上九，是往外开</li><li>心性是根，德是土，道是天</li><li>刚健笃实，辉光日新——每一天的积累，都在发光</li><li>能止健——不是压制冲动，是让冲动变成有秩序的、有德性的行动</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>大畜与 Dao-is-Coding 的映射：</p><ul><li><strong>九二舆说輹</strong>：有实绩，但整体差些火候——主动蓄，不是被动等</li><li><strong>九三闲舆卫</strong>：易经、奇门的真正内化，是驾驭「Dao 核心理论」这匹良马的能力；以德彰显、运用到软件开发，才是真正的独特竞争力</li><li><strong>六五豮豕之牙</strong>：写文的目的是「想写」，不是「想被夸」——这两者之间的距离，就是心性要走的路</li></ul><p>多年后，才能于易彬彬亦。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：无妄（第二十五卦）、颐（第二十七卦）</li><li>无妄与大畜：无妄而后大畜——不妄动，才谈得上蓄养</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',19))])}}});export{y as __pageData,x as default};
